(() => {
  function findInShadow(root, selector) {
    if (!root) return null;
    const found = root.querySelector ? root.querySelector(selector) : null;
    if (found) return found;
    const all = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of all) {
      if (el.shadowRoot) {
        const r = findInShadow(el.shadowRoot, selector);
        if (r) return r;
      }
    }
    return null;
  }
  const sel = findInShadow(document, 'settings-search-engines-page, settings-search-page');
  return sel ? sel.tagName : 'none';
})()
""",
    "returnByValue": True
})
print("found:", res)
ws.close()
