import websocket, json, time, os
for v in ['HTTP_PROXY','HTTPS_PROXY','http_proxy','https_proxy']:
    os.environ.pop(v, None)
import urllib.request

data = json.loads(urllib.request.urlopen("http://localhost:1337/json/list").read())
page = next(t for t in data if t.get('type')=='page')
ws_url = page['webSocketDebuggerUrl']

ws = websocket.create_connection(ws_url)
msg_id = 0
def send(method, params=None):
    global msg_id
    msg_id += 1
    cur_id = msg_id
    ws.send(json.dumps({"id": cur_id, "method": method, "params": params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get("id") == cur_id:
            return msg

send("Page.enable")
send("Runtime.enable")

# Make sure we're on the settings page
send("Page.navigate", {"url": "chrome://settings/search"})
time.sleep(3)

# Recurse through shadow DOM to find select elements
js = r"""
(() => {
  const out = [];
  function walk(root, depth=0) {
    if (!root) return;
    let nodes = [];
    if (root.querySelectorAll) nodes = root.querySelectorAll('*');
    for (const el of nodes) {
      if (el.tagName === 'SELECT') {
        const opts = [...el.options].map(o => ({value: o.value, text: o.textContent.trim()}));
        out.push({id: el.id, name: el.name, depth, opts});
      }
      if (el.shadowRoot) walk(el.shadowRoot, depth+1);
    }
  }
  walk(document, 0);
  return out;
})()
"""
res = send("Runtime.evaluate", {"expression": js, "returnByValue": True})
print(json.dumps(res.get("result",{}).get("result",{}).get("value"), indent=2))

ws.close()
