import websocket, json, time, os
for v in ['HTTP_PROXY','HTTPS_PROXY','http_proxy','https_proxy']:
    os.environ.pop(v, None)
import urllib.request
data = json.loads(urllib.request.urlopen("http://localhost:1337/json/list").read())
page = next(t for t in data if t.get('type')=='page')
ws = websocket.create_connection(page['webSocketDebuggerUrl'])
msg_id = 0
def send(method, params=None):
    global msg_id; msg_id += 1; cur=msg_id
    ws.send(json.dumps({"id":cur,"method":method,"params":params or {}}))
    while True:
        m = json.loads(ws.recv())
        if m.get("id")==cur: return m

send("Page.enable"); send("Runtime.enable")

# Make sure we're on settings page
res = send("Runtime.evaluate", {"expression":"location.href","returnByValue":True})
url = res.get("result",{}).get("result",{}).get("value","")
if "chrome://settings/search" not in url:
    send("Page.navigate", {"url":"chrome://settings/search"})
    time.sleep(3)

js = r"""
(() => {
  function findSel(root) {
    if (!root) return null;
    let nodes = root.querySelectorAll ? root.querySelectorAll('select') : [];
    for (const el of nodes) {
      const vals = [...el.options].map(o => o.value);
      if (vals.includes('Bing') && vals.includes('Google')) return el;
    }
    let all = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of all) {
      if (el.shadowRoot) {
        const r = findSel(el.shadowRoot);
        if (r) return r;
      }
    }
    return null;
  }
  const sel = findSel(document);
  if (!sel) return {ok:false, reason:'select not found'};
  const before = sel.value;
  sel.value = 'Bing';
  sel.dispatchEvent(new Event('change', {bubbles:true}));
  return {ok:true, before, after: sel.value};
})()
